draw:
const th = p.angle * Math.PI / 180;
const m = p.mass, g = 9.8;
const a = g * Math.sin(th);
const N = m * g * Math.cos(th);

const pad = 26;
const baseY = H - pad;
const baseX = pad;
const len = (W - pad * 2) * 0.78;
const topY = baseY - len * Math.tan(th);

// incline
ctx.lineWidth = 1.5;
ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(baseX, baseY);
ctx.lineTo(baseX + len, baseY);
ctx.lineTo(baseX + len, topY);
ctx.closePath();
ctx.stroke();

// angle label at the bottom-left corner
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.arc(baseX, baseY, 26, -th, 0);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("theta = " + p.angle.toFixed(0) + " deg", baseX + 30, baseY - 6);

// block slides from the top, restarts
const sMax = len / Math.cos(th) * 0.72;
const tRun = Math.sqrt(2 * sMax / Math.max(a, 0.001));
const now = (t % (tRun + 0.8));
const s = Math.min(0.5 * a * now * now, sMax);
const startX = baseX + len - sMax * Math.cos(th);
const startY = topY + sMax * Math.sin(th);
const bx = startX + s * Math.cos(th);
const by = startY - s * Math.sin(th);

// block drawn as a small square sitting on the surface
const bs = 16;
ctx.save();
ctx.translate(bx, by);
ctx.rotate(-th);
ctx.fillStyle = C.accent;
ctx.fillRect(-bs / 2, -bs, bs, bs);
ctx.restore();

function arrow(x0, y0, x1, y1, col, label) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();
  const ang = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(ang - 0.4), y1 - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x1 - 7 * Math.cos(ang + 0.4), y1 - 7 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fill();
  ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
  ctx.fillText(label, x1 + 4, y1 - 2);
}

// centre of the block, lifted half a block along the surface normal
const cx = bx - (bs / 2) * Math.sin(th);
const cy = by - (bs / 2) * Math.cos(th);
const k = 3.2;

// weight, straight down
arrow(cx, cy, cx, cy + m * g * k * 0.55, C.figure, "mg");
// component along the surface (down-slope)
arrow(cx, cy, cx + m * g * Math.sin(th) * k * Math.cos(th) * 0.55,
      cy + m * g * Math.sin(th) * k * Math.sin(th) * 0.55, C.accent, "mg sin");
// component into the surface
arrow(cx, cy, cx - m * g * Math.cos(th) * k * Math.sin(th) * 0.55,
      cy + m * g * Math.cos(th) * k * Math.cos(th) * 0.55, C.accent, "mg cos");
// normal force, out of the surface
arrow(cx, cy, cx - N * k * Math.sin(th) * 0.55, cy - N * k * Math.cos(th) * 0.55,
      C.ink, "N");

// tilted axis hint
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(cx - 40 * Math.cos(th), cy + 40 * Math.sin(th));
ctx.lineTo(cx + 40 * Math.cos(th), cy - 40 * Math.sin(th));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("x along surface", pad, pad + 2);
ctx.fillText("y perpendicular", pad, pad + 16);

out.note = "a = g sin(theta) = " + a.toFixed(2) + " m/s^2   |   N = mg cos(theta) = " + N.toFixed(1) + " N   |   weight mg = " + (m * g).toFixed(1) + " N";

ctx.lineWidth = 1.6;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x0, y0, x1, y1, col, label, above) {
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();
  const ang = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(ang - 0.4), y1 - 7 * Math.sin(ang - 0.4));
  ctx.lineTo(x1 - 7 * Math.cos(ang + 0.4), y1 - 7 * Math.sin(ang + 0.4));
  ctx.closePath();
  ctx.fill();
  ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
  ctx.fillText(label, (x0 + x1) / 2 - 10, above ? Math.min(y0, y1) - 6 : Math.max(y0, y1) + 14);
}

const halfW = W / 2;
const groundY = H * 0.62;

// ---- left panel: the pair as one system ----
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(W * 0.04, groundY);
ctx.lineTo(halfW - W * 0.03, groundY);
ctx.stroke();

const aW = W * 0.10, bW = W * 0.13, bh = H * 0.20;
const ax0 = W * 0.16;
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.paper;
ctx.fillRect(ax0, groundY - bh, aW, bh);
ctx.strokeRect(ax0, groundY - bh, aW, bh);
ctx.fillRect(ax0 + aW, groundY - bh, bW, bh);
ctx.strokeRect(ax0 + aW, groundY - bh, bW, bh);
ctx.fillStyle = C.ink;
ctx.fillText("3 kg", ax0 + 4, groundY - bh / 2);
ctx.fillText("5 kg", ax0 + aW + 6, groundY - bh / 2);

// dashed system boundary around both
ctx.strokeStyle = C.accent;
ctx.setLineDash([5, 4]);
ctx.strokeRect(ax0 - 9, groundY - bh - 9, aW + bW + 18, bh + 18);
ctx.setLineDash([]);

arrow(ax0 - 48, groundY - bh / 2, ax0 - 11, groundY - bh / 2, C.figure, "F = 12 N", true);
ctx.fillStyle = C.accent;
ctx.fillText("system: both blocks", W * 0.05, H * 0.14);
ctx.fillStyle = C.ink;
ctx.fillText("contact force is internal", W * 0.05, H * 0.14 + 16);
ctx.fillText("a = F / (3 + 5) = 1.5 m/s^2", W * 0.05, H * 0.14 + 32);

// divider
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(halfW, H * 0.06);
ctx.lineTo(halfW, H * 0.94);
ctx.stroke();

// ---- right panel: cut the system, isolate the front block ----
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(halfW + W * 0.04, groundY);
ctx.lineTo(W * 0.96, groundY);
ctx.stroke();

const cx0 = halfW + W * 0.22;
ctx.strokeStyle = C.rule;
ctx.fillStyle = C.paper;
ctx.fillRect(cx0, groundY - bh, aW, bh);
ctx.strokeRect(cx0, groundY - bh, aW, bh);
ctx.fillStyle = C.ink;
ctx.fillText("3 kg", cx0 + 4, groundY - bh / 2);

ctx.strokeStyle = C.accent;
ctx.setLineDash([5, 4]);
ctx.strokeRect(cx0 - 9, groundY - bh - 9, aW + 18, bh + 18);
ctx.setLineDash([]);

arrow(cx0 - 48, groundY - bh / 2, cx0 - 11, groundY - bh / 2, C.figure, "F = 12 N", true);
arrow(cx0 + aW + 48, groundY - bh / 2, cx0 + aW + 11, groundY - bh / 2, C.figure, "C = 7.5 N", true);
arrow(cx0 + aW / 2, groundY - bh - 12, cx0 + aW / 2, groundY - bh - 44, C.ink, "N", false);
arrow(cx0 + aW / 2, groundY - bh / 2, cx0 + aW / 2, groundY + 26, C.ink, "mg", false);

ctx.fillStyle = C.accent;
ctx.fillText("system: front block only", halfW + W * 0.04, H * 0.14);
ctx.fillStyle = C.ink;
ctx.fillText("contact force is now external", halfW + W * 0.04, H * 0.14 + 16);
ctx.fillText("12 - C = 3 x 1.5, so C = 7.5 N", halfW + W * 0.04, H * 0.14 + 32);

const g = 9.8;
const m1 = p.m1, m2 = p.m2;
const a = (m1 - m2) * g / (m1 + m2);
const T = 2 * m1 * m2 * g / (m1 + m2);

const pad = 26;
const panelW = W * 0.44;

// ---- left: the machine, animated ----
const pulX = panelW * 0.5, pulY = pad + 8, R = 14;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath();
ctx.arc(pulX, pulY, R, 0, Math.PI * 2);
ctx.stroke();

const span = H - pulY - pad - 30;
const cycle = 1.6;
const ph = ((t % (2 * cycle)) / cycle);
const frac = ph < 1 ? ph : 2 - ph;
const dir = a >= 0 ? 1 : -1;
const shift = dir * (frac - 0.5) * span * 0.35 * Math.min(1, Math.abs(a) / g);

const y1 = pulY + span * 0.45 + shift;
const y2 = pulY + span * 0.45 - shift;

ctx.strokeStyle = C.rule;
ctx.beginPath();
ctx.moveTo(pulX - R, pulY);
ctx.lineTo(pulX - R, y1);
ctx.moveTo(pulX + R, pulY);
ctx.lineTo(pulX + R, y2);
ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
const bw = 30, bh = 20;
ctx.fillStyle = C.accent;
ctx.fillRect(pulX - R - bw / 2, y1, bw, bh);
ctx.fillRect(pulX + R - bw / 2, y2, bw, bh);
ctx.fillStyle = C.ink;
ctx.fillText("m1 = " + m1.toFixed(1) + " kg", pulX - R - bw / 2 - 6, y1 + bh + 16);
ctx.fillText("m2 = " + m2.toFixed(1) + " kg", pulX + R - bw / 2 - 6, y2 + bh + 16);
ctx.fillStyle = C.figure;
ctx.fillText("T = " + T.toFixed(1) + " N", pulX - 24, pulY + span * 0.18);

// ---- right: a against m1, with the two limits marked ----
const gx0 = panelW + 40, gx1 = W - pad;
const gy0 = pad + 6, gy1 = H - pad - 14;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath();
ctx.moveTo(gx0, gy0);
ctx.lineTo(gx0, gy1);
ctx.lineTo(gx1, gy1);
ctx.stroke();
// zero line (a = 0 sits in the middle)
const Ay = v => gy1 - (v + g) / (2 * g) * (gy1 - gy0);
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath();
ctx.moveTo(gx0, Ay(0));
ctx.lineTo(gx1, Ay(0));
ctx.moveTo(gx0, Ay(g));
ctx.lineTo(gx1, Ay(g));
ctx.moveTo(gx0, Ay(-g));
ctx.lineTo(gx1, Ay(-g));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.faint;
ctx.font = "11px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("a = +g", gx0 + 4, Ay(g) + 12);
ctx.fillText("a = 0", gx0 + 4, Ay(0) - 4);
ctx.fillText("a = -g", gx0 + 4, Ay(-g) - 4);
ctx.fillText("m1 (kg)", gx1 - 46, gy1 + 12);

const mMax = 10;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (let i = 0; i <= 120; i++) {
  const mm = 0.1 + (mMax - 0.1) * i / 120;
  const av = (mm - m2) * g / (mm + m2);
  const X = gx0 + (mm / mMax) * (gx1 - gx0);
  i === 0 ? ctx.moveTo(X, Ay(av)) : ctx.lineTo(X, Ay(av));
}
ctx.stroke();

const mx = gx0 + (Math.min(m1, mMax) / mMax) * (gx1 - gx0);
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.arc(mx, Ay(a), 4.5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("a vs m1 at fixed m2", gx0 + 4, gy0 + 12);

out.note = "a = (m1 - m2)g/(m1 + m2) = " + a.toFixed(2) + " m/s^2   |   T = 2 m1 m2 g/(m1 + m2) = " + T.toFixed(1) + " N   |   set m1 = m2 and a goes to 0; make m2 tiny and a goes to g";
